let rows = 51;
let cols = 11;
let sz = 5;
let xSpacing = 50;
let ySpacing = 6;

function setup() {
	createCanvas(1080, 1080);
	// gen();
		strokeWeight(2);
	stroke(255);
	fill(0);

}

function draw() {
	background(0);

	// -1 since we account for the 'last' item in the row/col to not have an adjacent tile
	let gridWidth =  cols * sz + ((cols-1) * xSpacing);
	let gridHeight = rows * sz + ((rows-1) * ySpacing);

	push();
	translate(width/2 - gridWidth/2, height/2 - gridHeight/2);

	for(let y = 0; y < rows; y++){
		for(let x = 0; x < cols; x++){
			push();
			translate(x * sz + (x*xSpacing), y * sz + (y * ySpacing));
			// rect(0, 0, sz, sz);

			let offset = (x+(frameCount/100) % 2) * TAU * 2;
			let size = (sin((y+offset)/rows * TAU * 2)+1)/2 ;

			ellipse(0, 0, 10 + size * 70 );
			// arc(0,0, size*70, size*70, -0.25, PI+0.25);

			pop();
		}
	}

	pop();
	// // noLoop() removed for animation
}

